"use client"

import type { NavSection } from "@/components/blocks/sidebar-shared/sidebar-data"
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu"
import { Icon } from "@/components/ui/icon"
import { SidebarGroup, SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar"

export function NavMain({ items }: { items: NavSection[] }) {
  const { isMobile } = useSidebar()

  return (
    <SidebarGroup>
      <SidebarMenu>
        {items.map((section) => {
          const holdsCurrent = section.items.some((item) => item.isActive)
          return (
            <SidebarMenuItem key={section.title}>
              <DropdownMenu>
                <DropdownMenuTrigger asChild>
                  <SidebarMenuButton isActive={holdsCurrent} aria-current={holdsCurrent ? "true" : undefined} className="data-[state=open]:ll-swipe">
                    {section.title}
                    <Icon name="ellipsis" className="ms-auto" />
                  </SidebarMenuButton>
                </DropdownMenuTrigger>
                {section.items.length ? (
                  <DropdownMenuContent side={isMobile ? "bottom" : "right"} align={isMobile ? "end" : "start"} className="min-w-56">
                    {section.items.map((item) => (
                      <DropdownMenuItem asChild key={item.title}>
                        <a href={item.url} aria-current={item.isActive ? "page" : undefined} className={item.isActive ? "font-bold" : undefined}>
                          {item.title}
                          {item.isActive ? <Icon name="check" className="ms-auto" /> : null}
                        </a>
                      </DropdownMenuItem>
                    ))}
                  </DropdownMenuContent>
                ) : null}
              </DropdownMenu>
            </SidebarMenuItem>
          )
        })}
      </SidebarMenu>
    </SidebarGroup>
  )
}

"use client"

import * as React from "react"

import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Label } from "@/components/ui/label"
import { SidebarInput } from "@/components/ui/sidebar"

export function SidebarOptInForm({ onSubmit }: { onSubmit?: (email: string) => void }) {
  const id = React.useId()
  const [sent, setSent] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)

  return (
    <Card className="gap-2 py-4">
      <CardHeader className="px-4">
        <CardTitle className="text-xl">Get the postcard</CardTitle>
        <CardDescription>A short note on new pens and papers, every other Friday. Only ink, no spam.</CardDescription>
      </CardHeader>
      <CardContent className="px-4">
        {sent ? (
          <p role="status" className="font-hand text-sm text-green">
            Thank you! Watch your mailbox on Friday.
          </p>
        ) : (
          <form
            className="grid gap-2.5"
            noValidate
            onSubmit={(event) => {
              event.preventDefault()
              const value = new FormData(event.currentTarget).get("email")
              const email = typeof value === "string" ? value.trim() : ""
              if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
                setError("That does not look like an email address yet.")
                return
              }
              setError(null)
              onSubmit?.(email)
              setSent(true)
            }}
          >
            <Label htmlFor={id} className="sr-only">
              Email address
            </Label>
            <SidebarInput
              id={id}
              name="email"
              type="email"
              autoComplete="email"
              required
              placeholder="you@example.com"
              aria-invalid={error ? true : undefined}
              aria-describedby={error ? `${id}-error` : undefined}
              onChange={() => error && setError(null)}
            />
            {error ? (
              <p id={`${id}-error`} role="alert" className="font-hand text-sm text-red">
                {error}
              </p>
            ) : null}
            <Button size="sm" className="w-full" type="submit">
              Subscribe
            </Button>
          </form>
        )}
      </CardContent>
    </Card>
  )
}
